module div_8bit (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    input res_ready,
    output reg res_valid,
    output [15:0] result
);

    // Internal signals
    reg [7:0] dividend_abs;
    reg [7:0] divisor_extend;
    reg [8:0] NEG_DIVISOR;
    reg [9:0] all_sub_result;
    reg [8:0] sub_result;
    reg [9:0] REMAINDER;
    reg [15:0] SR;
    reg [7:0] QUOTIENT;
    reg CO;
    reg [8:0] mux_result;
    reg [6:0] quotient_shift;
    reg start_cnt;

    // Combinational logic
    assign dividend_abs = sign && dividend[7] ? ~dividend + 1 : dividend;
    assign divisor_extend = sign && divisor[7] ? {1'b1, divisor} : {1'b0, divisor};
    assign sub_result = SR[15:7];
    assign CO = all_sub_result[9];
    assign mux_result = CO ? sub_result : REMAINDER;
    assign quotient_shift = SR[14:8];
    assign final_remainer = sign && dividend_abs[7] ? ~REMAINDER + 1 : REMAINDER;
    assign final_quotient = sign && dividend_abs[7] ? ~QUOTIENT + 1 : QUOTIENT;
    assign is_final_quotient_sign = sign && (dividend_abs[7] ^ divisor[7]);

    // Sequential logic
    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            start_cnt <= 0;
            SR <= 0;
            res_valid <= 0;
        end else if (opn_valid && !start_cnt) begin
            start_cnt <= 1;
            SR <= {dividend_abs, 1'b0};
            NEG_DIVISOR <= divisor_extend;
        end else if (start_cnt) begin
            if (CO) begin
                SR <= {mux_result, quotient_shift, CO, 1'b0};
            end else begin
                SR <= {mux_result, quotient_shift, CO, 1'b0};
            end
            if (start_cnt == 8) begin
                start_cnt <= 0;
                SR <= {SR[7:0], mux_result[0]};
                res_valid <= 1;
            end
        end
    end

    // Result construction
    assign result = {final_remainer, final_quotient};

endmodule
